-- V20 — outbound dispatch, Wave 1: closure compliance + show-the-numbers.
-- Generated: closure form gains an Invoice-count check + a QR; the closure
-- inbox's one-click bypass becomes 'open the checklist form'; the close
-- transition gets a guard requiring all 3 checks; PMT + Billing lists finally
-- show the weights / quantities the operator must judge against.

ALTER TABLE gate_pass ADD COLUMN IF NOT EXISTS invoice_count_verified VARCHAR(8) NULL;
INSERT INTO entity_field_registry
  (id, tenant_id, entity_code, field_code, display_label, data_type, filterable, sortable, searchable, required, widget_kind, options_json)
SELECT (SELECT COALESCE(MAX(id),0)+1 FROM entity_field_registry x), -1, 'GatePass', 'invoice_count_verified', 'Invoice Count Verified', 'STRING', 1, 1, 0, 0, 'select',
  '[{"label":"YES","value":"YES"},{"label":"NO","value":"NO"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM entity_field_registry WHERE entity_code='GatePass' AND field_code='invoice_count_verified');

UPDATE page_version SET body_json='{"kind": "layout", "schemaVersion": 2, "slug": "aria:gate-pass-closure-form", "title": "Gate Pass Closure — Final Checks", "status": "published", "version": 1, "roles": ["FrontGate", "Dispatch", "Manager", "TenantAdmin"], "dataSources": [], "streams": [], "layout": [{"kind": "QrCode", "title": "Gate Pass", "entity": "GatePass", "idParam": "id", "qrField": "gp_number", "caption": "Scan to confirm before release.", "size": 150, "details": [{"field": "vehicle_no", "label": "Vehicle"}, {"field": "flow_variant_code", "label": "Flow"}]}, {"kind": "Grid", "columns": 12, "gap": 16, "children": [{"kind": "Section", "title": "Vehicle Summary (auto-fill from workflow)", "span": 12, "children": [{"kind": "Form", "submitLabel": "", "bindings": {"fields": [{"name": "gp_number", "label": "Gate Pass #", "type": "text", "readOnly": true}, {"name": "vehicle_no", "label": "Vehicle", "type": "text", "readOnly": true}, {"name": "flow_summary", "label": "Flow Summary", "type": "text", "readOnly": true, "helperText": "e.g. Tanker Unloading · 9,120 kg into TANK-1 · W2-W3 diff 0 kg · Sealed"}, {"name": "total_time_min", "label": "Total Time on Site (minutes)", "type": "number", "readOnly": true}]}}]}, {"kind": "Section", "title": "Final Gate Checks", "span": 12, "subtitle": "All checks must be ✓ or status will be HOLD", "children": [{"kind": "Form", "submitLabel": "", "bindings": {"fields": [{"name": "seal_verified", "label": "Seal verified at gate", "type": "select", "required": true, "options": [{"label": "✓ Number matches (system-generated)", "value": "MATCHED"}, {"label": "✗ Mismatch — hard block", "value": "MISMATCH"}, {"label": "N/A (no seal flow)", "value": "NA"}]}, {"kind": "FormField", "name": "invoice_count_verified", "type": "select", "required": true, "label": "Invoice count verified", "options": [{"label": "✓ Counted & matches", "value": "YES"}, {"label": "✗ Not verified", "value": "NO"}]}, {"name": "qc_clearance", "label": "QC clearance", "type": "select", "required": true, "options": [{"label": "✓ Approved", "value": "APPROVED"}, {"label": "✗ Rejected", "value": "REJECTED"}]}, {"name": "weighment_verified", "label": "Weighment verified (W1/W2/W3)", "type": "select", "required": true, "options": [{"label": "✓ All within tolerance", "value": "OK"}, {"label": "⚠ Manager-approved variance", "value": "MGR_APPROVED"}, {"label": "✗ Pending", "value": "PENDING"}]}, {"name": "order_recon_done", "label": "Order vs Unloaded reconciled", "type": "select", "required": true, "options": [{"label": "✓ Yes — within tolerance", "value": "OK"}, {"label": "⚠ Manager-approved discrepancy", "value": "MGR_APPROVED"}, {"label": "✗ No", "value": "NO"}]}, {"name": "within_tolerance", "label": "All checks clear?", "type": "select", "required": true, "options": [{"label": "YES — release vehicle", "value": "YES"}, {"label": "NO — route to manager", "value": "NO"}]}]}}]}, {"kind": "Section", "span": 12, "children": [{"kind": "WorkflowActionButton", "action": "workflow.transition", "label": "Close Gate Pass — Release Vehicle", "variant": "primary"}]}]}]}' WHERE id=704;

